ICE in module serialization - bad file data
Minimal repro:

// m-part.mxx
export module m:part;

template < int n >
struct Base
{
	static constexpr auto base_static_mbr_n = n;
};

template < int n >
struct Derived : Base< n >
{
	using Base< n >::base_static_mbr_n;

	template < int n2 >
		requires (n2 <= base_static_mbr_n)
	Derived()
	{}
};

struct S
{
    Derived< 1 > data;
};


// m.mxx
export module m;

export import :part;


